<template>
  <el-container class="app-shell" :class="[`nav-${settings.navMode}`, `sidebar-${settings.sideTheme}`, { 'header-static': !settings.fixedHeader }]" :style="themeStyle">
    <el-aside v-if="settings.navMode !== 'top'" :width="sidebarCollapsed ? '64px' : '220px'" class="app-aside">
      <div v-if="settings.showLogo" class="brand" @click="router.push('/dashboard')"><div class="brand-mark">SC</div><div v-if="!sidebarCollapsed" class="brand-copy"><strong>工程管理</strong><span>SMART CONSTRUCTION</span></div></div>
      <el-scrollbar class="nav-scroll"><el-menu :default-active="route.fullPath" :default-openeds="openMenus" :collapse="sidebarCollapsed" :unique-opened="true" :collapse-transition="false" router><app-menu-node v-for="item in sideMenus" :key="item.key" :item="item" :collapsed="sidebarCollapsed" /></el-menu></el-scrollbar>
      <div v-if="!sidebarCollapsed" class="aside-footer"><span>SC Platform</span><small>v{{ session.user ? '17' : '—' }}</small></div>
    </el-aside>
    <el-container class="main-frame">
      <div class="header-stack">
        <el-header class="app-header">
          <div class="header-left">
            <el-button v-if="settings.navMode !== 'top'" text class="collapse-button" @click="collapsed = !collapsed"><el-icon><Expand v-if="sidebarCollapsed" /><Fold v-else /></el-icon></el-button>
            <el-breadcrumb v-if="settings.navMode === 'side'" separator="/"><el-breadcrumb-item>工程管理平台</el-breadcrumb-item><el-breadcrumb-item>{{ currentTitle }}</el-breadcrumb-item></el-breadcrumb>
            <el-menu v-else-if="settings.navMode === 'mix'" mode="horizontal" :default-active="mixRootKey" :ellipsis="true" class="top-menu" @select="selectMixRoot"><el-menu-item v-for="item in topMenus" :key="item.key" :index="item.key"><el-icon><component :is="item.icon" /></el-icon><span>{{ item.label }}</span></el-menu-item></el-menu>
            <el-menu v-else mode="horizontal" :default-active="route.fullPath" :ellipsis="true" router class="top-menu"><app-menu-node v-for="item in topMenus" :key="item.key" :item="item" /></el-menu>
          </div>
          <div class="header-actions">
            <business-context-switcher />
            <el-popover v-model:visible="notificationPopover" placement="bottom-end" :width="380" trigger="click" popper-class="notification-popover">
              <template #reference><el-badge :value="unreadNotifications" :hidden="!unreadNotifications" :max="99" class="notification-badge"><el-button text circle aria-label="消息中心"><el-icon><Bell /></el-icon></el-button></el-badge></template>
              <div class="notification-popup">
                <div class="notification-popup__header"><strong>通知公告</strong><el-button link type="primary" :disabled="!unreadNotifications" @click="markAllNotificationsRead">全部已读</el-button></div>
                <div v-if="recentNotifications.length" class="notification-popup__list">
                  <button v-for="item in recentNotifications" :key="item.id" class="notification-popup__item" :class="{ unread: !item.is_read }" @click="openNotificationItem(item)">
                    <el-tag size="small" :type="notificationKind(item)==='公告'?'success':'warning'" effect="light">{{ notificationKind(item) }}</el-tag>
                    <span class="notification-popup__copy"><strong>{{ item.sc_subject||item.sc_record_name||'业务消息' }}</strong><small>{{ notificationText(item.sc_body)||'暂无消息内容' }}</small></span>
                    <time>{{ notificationTime(item.sc_message_date) }}</time>
                  </button>
                </div>
                <el-empty v-else description="暂无消息" :image-size="52" />
                <button class="notification-popup__footer" @click="openNotifications">查看全部消息</button>
              </div>
            </el-popover>
            <el-tooltip content="布局设置"><el-button text circle aria-label="布局设置" @click="settingsRef?.open()"><el-icon><Setting /></el-icon></el-button></el-tooltip>
            <el-dropdown @command="handleCommand"><span class="user-trigger"><el-avatar :size="30" class="avatar">{{ session.displayName.slice(0, 1) }}</el-avatar><span class="user-name">{{ session.displayName }}</span><el-icon><ArrowDown /></el-icon></span><template #dropdown><el-dropdown-menu><el-dropdown-item command="profile"><el-icon><User /></el-icon>个人资料</el-dropdown-item><el-dropdown-item command="diagnostics"><el-icon><Monitor /></el-icon>运行诊断</el-dropdown-item><el-dropdown-item divided command="logout"><el-icon><SwitchButton /></el-icon>退出登录</el-dropdown-item></el-dropdown-menu></template></el-dropdown>
          </div>
        </el-header>
        <tags-view v-if="settings.showTabs" />
      </div>
      <el-main class="app-main"><router-view v-slot="{ Component, route: viewRoute }"><KeepAlive :max="30"><component :is="Component" :key="viewRoute.fullPath" /></KeepAlive></router-view><footer v-if="settings.showFooter" class="app-footer">Copyright © 2026 Smart Construction Platform</footer></el-main>
    </el-container>
    <layout-settings ref="settingsRef" />
  </el-container>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessageBox } from 'element-plus'
import { ArrowDown, Bell, Expand, Fold, Monitor, Setting, SwitchButton, User } from '@element-plus/icons-vue'
import AppMenuNode from '@/components/AppMenuNode.vue'
import BusinessContextSwitcher from '@/components/BusinessContextSwitcher.vue'
import LayoutSettings from '@/components/LayoutSettings.vue'
import TagsView from '@/components/TagsView.vue'
import { listNotifications, setNotificationRead } from '@/api/odoo'
import type { Dictionary } from '@/types/contracts'
import { useLayoutStore } from '@/stores/layout'
import { useSessionStore } from '@/stores/session'
import { activeGroupIndexes, type MenuItem, useNavigation } from '@/utils/navigation'

const route=useRoute();const router=useRouter();const session=useSessionStore();const layout=useLayoutStore();const collapsed=ref(false);const narrowViewport=ref(false);const unreadNotifications=ref(0);const notificationRows=ref<Dictionary[]>([]);const recentNotifications=computed(()=>notificationRows.value.slice(0,6));const notificationPopover=ref(false);const sidebarCollapsed=computed(()=>collapsed.value||narrowViewport.value);const settingsRef=ref<InstanceType<typeof LayoutSettings>>();const settings=computed(()=>layout.settings);const menus=computed(()=>useNavigation(session.navigation));const rootMenus=computed(()=>flattenSystemRoot(menus.value));const mixRootKey=ref('');const topMenus=computed(()=>rootMenus.value);const activeRoot=computed(()=>rootMenus.value.find((item)=>item.key===mixRootKey.value)||rootMenus.value[0]);const sideMenus=computed(()=>settings.value.navMode==='mix'?(activeRoot.value?.children.length?activeRoot.value.children:activeRoot.value?[activeRoot.value]:[]):rootMenus.value);const openMenus=computed(()=>activeGroupIndexes(sideMenus.value,route.fullPath));const currentMenu=computed(()=>findMenuItem(rootMenus.value,route.fullPath)||findMenuByBackendIdentity(rootMenus.value,Number(route.query.action_id||route.params.actionId||0),Number(route.query.menu_id||0)));const baseTitle=computed(()=>currentMenu.value?.label||String(route.meta.title||'工作台'));const currentTitle=computed(()=>{if(!route.path.startsWith('/record/'))return baseTitle.value;const id=String(route.params.id||'');const mode=String(route.query.mode||'view');return `${baseTitle.value} - ${id==='new'?'新建':mode==='edit'?'编辑':'详情'}`});const themeStyle=computed(()=>({'--el-color-primary':settings.value.primaryColor,'--el-color-primary-light-9':colorMix(settings.value.primaryColor,'#ffffff',.9),'--el-color-primary-light-5':colorMix(settings.value.primaryColor,'#ffffff',.5)}))
let mediaQuery:MediaQueryList|undefined
let notificationTimer:number|undefined
function syncViewport(event:MediaQueryListEvent|MediaQueryList){narrowViewport.value=event.matches}
function syncNotificationCount(event:Event){unreadNotifications.value=Number((event as CustomEvent).detail?.unread||0)}
async function loadNotificationCount(){try{const result=await listNotifications(100);const rows=result.records||result.rows||[];notificationRows.value=rows;unreadNotifications.value=rows.filter((item)=>!item.is_read).length}catch{return}}
onMounted(()=>{mediaQuery=window.matchMedia('(max-width: 900px)');syncViewport(mediaQuery);mediaQuery.addEventListener('change',syncViewport);window.addEventListener('sce:notifications-updated',syncNotificationCount);void loadNotificationCount();notificationTimer=window.setInterval(loadNotificationCount,60_000)})
onBeforeUnmount(()=>{mediaQuery?.removeEventListener('change',syncViewport);window.removeEventListener('sce:notifications-updated',syncNotificationCount);if(notificationTimer)window.clearInterval(notificationTimer)})
function flattenSystemRoot(items:MenuItem[]){return items.length===1&&/系统菜单/.test(items[0].label)&&!items[0].executable?items[0].children:items}function findMenuItem(items:MenuItem[],fullPath:string):MenuItem|undefined{for(const item of items){if(item.route===fullPath)return item;const child=findMenuItem(item.children,fullPath);if(child)return child}return undefined}function findMenuByBackendIdentity(items:MenuItem[],actionId:number,menuId:number):MenuItem|undefined{for(const item of items){if((menuId&&item.menuId===menuId)||(actionId&&item.actionId===actionId))return item;const child=findMenuByBackendIdentity(item.children,actionId,menuId);if(child)return child}return undefined}function findMenuByLabel(items:MenuItem[],label:string):MenuItem|undefined{for(const item of items){if(item.label===label)return item;const child=findMenuByLabel(item.children,label);if(child)return child}return undefined}function containsMenuKey(item:MenuItem,key:string):boolean{return item.key===key||item.children.some((child)=>containsMenuKey(child,key))}function findRootForCurrentMenu(items:MenuItem[],menu:MenuItem|undefined):MenuItem|undefined{return menu?items.find((item)=>containsMenuKey(item,menu.key)):undefined}function colorMix(color:string,target:string,amount:number){const source=color.replace('#','');const destination=target.replace('#','');if(source.length!==6||destination.length!==6)return color;const channels=[0,2,4].map((offset)=>Math.round(parseInt(source.slice(offset,offset+2),16)*(1-amount)+parseInt(destination.slice(offset,offset+2),16)*amount));return`#${channels.map((channel)=>channel.toString(16).padStart(2,'0')).join('')}`}function notificationText(value:unknown){const element=document.createElement('div');element.innerHTML=String(value||'');return(element.textContent||'').replace(/\s+/g,' ').trim()}function notificationTime(value:unknown){const text=String(value||'');return text?text.replace('T',' ').replace('Z','').slice(5,16):''}function notificationKind(item:Dictionary){return/公告|公示/.test(String(item.sc_subject||''))?'公告':'通知'}function openNotifications(){notificationPopover.value=false;void router.push(findMenuByLabel(rootMenus.value,'消息通知')?.route||'/notifications')}async function openNotificationItem(item:Dictionary){notificationPopover.value=false;if(!item.is_read){await setNotificationRead(Number(item.id),true);item.is_read=true;unreadNotifications.value=Math.max(0,unreadNotifications.value-1)}const model=String(item.sc_source_model||'');const id=Number(item.sc_source_res_id||0);if(model&&id)await router.push({name:'Record',params:{model,id},query:{mode:'view'}});else openNotifications()}async function markAllNotificationsRead(){const unread=notificationRows.value.filter((item)=>!item.is_read);await Promise.all(unread.map((item)=>setNotificationRead(Number(item.id),true)));unread.forEach((item)=>{item.is_read=true});await loadNotificationCount()}function selectMixRoot(key:string){mixRootKey.value=key;const item=rootMenus.value.find((row)=>row.key===key);if(item?.executable&&item.route)void router.push(item.route)}async function handleCommand(command:string){if(command==='profile')return router.push('/profile');if(command==='diagnostics')return router.push('/diagnostics');if(command==='logout'){await ElMessageBox.confirm('确定退出当前账号吗？','退出登录',{type:'warning'});await session.logout();await router.replace('/login')}}
watch([()=>route.fullPath,()=>settings.value.dynamicTitle,rootMenus],()=>{const root=findRootForCurrentMenu(rootMenus.value,currentMenu.value);if(root)mixRootKey.value=root.key;const title=currentTitle.value;if(!route.path.startsWith('/action/'))layout.addTab({fullPath:route.fullPath,path:route.path,title,icon:String(currentMenu.value?.icon||route.meta.icon||fallbackTabIcon(route.path)),closable:route.path!=='/dashboard'});document.title=settings.value.dynamicTitle?`${title} - 工程管理平台`:'工程管理平台'},{immediate:true,deep:true})
function fallbackTabIcon(path:string){if(path==='/dashboard')return'Odometer';if(path.startsWith('/record/'))return'EditPen';if(path.startsWith('/action/'))return'Document';if(path.startsWith('/scene/'))return'Monitor';return''}
</script>

