.main-frame{flex-direction:column}
.app-header :deep(.el-breadcrumb){flex:0 0 auto;white-space:nowrap}
.notification-badge :deep(.el-badge__content){transform:translate(35%,-35%)}
.notification-popup{margin:-12px;overflow:hidden}.notification-popup__header{height:48px;display:flex;align-items:center;justify-content:space-between;padding:0 16px;background:var(--el-fill-color-extra-light);border-bottom:1px solid var(--el-border-color-lighter)}.notification-popup__list{max-height:330px;overflow:auto}.notification-popup__item{width:100%;display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:10px;padding:12px 14px;border:0;border-bottom:1px solid var(--el-border-color-lighter);background:#fff;text-align:left;cursor:pointer}.notification-popup__item:hover{background:var(--el-fill-color-extra-light)}.notification-popup__item.unread .notification-popup__copy strong::after{content:'';display:inline-block;width:6px;height:6px;margin-left:6px;border-radius:50%;background:var(--el-color-danger);vertical-align:middle}.notification-popup__copy{display:grid;min-width:0;gap:4px}.notification-popup__copy strong,.notification-popup__copy small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.notification-popup__copy strong{color:var(--el-text-color-primary);font-size:13px}.notification-popup__copy small,.notification-popup__item time{color:var(--el-text-color-secondary);font-size:11px}.notification-popup__footer{width:100%;height:40px;border:0;background:#fff;color:var(--el-color-primary);cursor:pointer}.notification-popup__footer:hover{background:var(--el-fill-color-light)}
:deep(.app-aside .el-menu--collapse .menu-title){display:none}
@media(max-width:1100px){.app-aside{width:64px!important}.brand{padding:0 16px}.brand-copy,.aside-footer,.company-select,.user-name{display:none}.app-header{padding-right:12px}.app-main{padding:16px}.app-header :deep(.el-breadcrumb){display:none}.header-actions{gap:4px}.header-actions :deep(.business-context-switcher){gap:0}.header-actions :deep(.business-context-switcher .context-button){padding:8px 5px}.header-actions :deep(.business-context-switcher .context-button span){display:none}.nav-mix .top-menu,.nav-top .top-menu{display:none}}
</style>
